"""Generated by rua-dev contracts from schemas/openapi.json."""

from urllib.parse import quote

import httpx2
from pydantic import TypeAdapter

from hebbian_robot_use_client.contract.station_api import (
    ActionSequenceRecord,
    ActionSequenceStartRequest,
    CameraListing,
    CommandAccepted,
    CommandCancellationRequest,
    CommandRefused,
    CommandSubmissionRequest,
    GroupCommandSubmissionRequest,
    LeaseAcquireRequest,
    LeaseCameraReport,
    LeaseGrant,
    LeaseToken,
    PhoneInvite,
    PhoneInviteRequest,
    PosePreviewBatchRequest,
    PosePreviewBatchResponse,
    RecordingStatus,
    RunSpansRequest,
    StationInstance,
    StationState,
    TraceFile,
)


class StationApi:
    """One method per station HTTP route; the media service has its own client."""

    def __init__(self, station: httpx2.AsyncClient, media: httpx2.AsyncClient) -> None:
        self._station = station
        self._media = media

    async def close(self) -> None:
        await self._station.aclose()
        await self._media.aclose()

    @staticmethod
    async def _send(
        client: httpx2.AsyncClient,
        method: str,
        path: str,
        body: object = None,
    ) -> httpx2.Response:
        response = await client.request(
            method,
            path,
            content=None if body is None else TypeAdapter(object).dump_json(body),
            headers=None if body is None else {"Content-Type": "application/json"},
        )
        response.raise_for_status()
        return response

    async def start_action_sequence_http(self, body: ActionSequenceStartRequest) -> str:
        """Start an action sequence under a lease."""
        response = await self._send(self._station, "POST", "/action_sequence", body)
        return TypeAdapter(str).validate_json(response.content)

    async def get_action_sequence(self, id: str) -> ActionSequenceRecord:
        """A running or recently finished action sequence by identifier."""
        response = await self._send(
            self._station, "GET", f"/action_sequence/{quote(id, safe='')}"
        )
        return TypeAdapter(ActionSequenceRecord).validate_json(response.content)

    async def cancel_action_sequence_http(self, id: str) -> None:
        """Cancel an action sequence."""
        await self._send(
            self._station, "POST", f"/action_sequence/{quote(id, safe='')}/cancel"
        )

    async def stop_leased_arm_http(self, arm: str, body: LeaseToken) -> None:
        """Stop one arm while holding the lease."""
        await self._send(
            self._station, "POST", f"/arms/{quote(arm, safe='')}/stop", body
        )

    async def list_cameras(self) -> list[CameraListing]:
        """The cameras the media service knows."""
        response = await self._send(self._media, "GET", "/cameras")
        return TypeAdapter(list[CameraListing]).validate_json(response.content)

    async def get_camera(self, name: str) -> httpx2.Response:
        """The newest JPEG frame from a camera, with `X-Captured-At-Unix-Ns` when known."""
        return await self._send(self._media, "GET", f"/cameras/{quote(name, safe='')}")

    async def submit_command_http(
        self, body: CommandSubmissionRequest
    ) -> CommandAccepted | CommandRefused:
        """Submit an individual arm command."""
        response = await self._send(self._station, "POST", "/commands", body)
        return TypeAdapter(CommandAccepted | CommandRefused).validate_json(
            response.content
        )

    async def cancel_command_submission_http(
        self, body: CommandCancellationRequest
    ) -> None:
        """Cancel a submission and stop its arms while holding the lease."""
        await self._send(self._station, "POST", "/commands/cancel", body)

    async def submit_group_command_http(
        self, body: GroupCommandSubmissionRequest
    ) -> CommandAccepted | CommandRefused:
        """Submit a coordinated arm command."""
        response = await self._send(self._station, "POST", "/group_commands", body)
        return TypeAdapter(CommandAccepted | CommandRefused).validate_json(
            response.content
        )

    async def get_station_instance(self) -> StationInstance:
        """Identify the current station process."""
        response = await self._send(self._station, "GET", "/instance")
        return TypeAdapter(StationInstance).validate_json(response.content)

    async def acquire_lease_http(self, body: LeaseAcquireRequest) -> LeaseGrant:
        """Acquire or take the station lease."""
        response = await self._send(self._station, "POST", "/leases", body)
        return TypeAdapter(LeaseGrant).validate_json(response.content)

    async def report_lease_camera_http(self, body: LeaseCameraReport) -> None:
        """Report a required camera's availability."""
        await self._send(self._station, "POST", "/leases/camera", body)

    async def release_lease_http(self, body: LeaseToken) -> None:
        """Release a current station lease."""
        await self._send(self._station, "POST", "/leases/release", body)

    async def renew_lease_http(self, body: LeaseToken) -> None:
        """Renew a current station lease."""
        await self._send(self._station, "POST", "/leases/renew", body)

    async def preview_poses(
        self, body: PosePreviewBatchRequest
    ) -> PosePreviewBatchResponse:
        """Preview independent pose candidates for one arm in input order."""
        response = await self._send(self._station, "POST", "/pose_previews", body)
        return TypeAdapter(PosePreviewBatchResponse).validate_json(response.content)

    async def record_run_event_http(self, body: object) -> None:
        """Record a model-loop event."""
        await self._send(self._station, "POST", "/run/events", body)

    async def record_run_spans_http(self, body: RunSpansRequest) -> None:
        """Record model-loop span updates."""
        await self._send(self._station, "POST", "/run/spans", body)

    async def get_state(self) -> StationState:
        """The whole station."""
        response = await self._send(self._station, "GET", "/state")
        return TypeAdapter(StationState).validate_json(response.content)

    async def list_traces(self) -> list[TraceFile]:
        """The executor's trace files, newest first."""
        response = await self._send(self._station, "GET", "/traces")
        return TypeAdapter(list[TraceFile]).validate_json(response.content)

    async def get_trace_file(self, name: str) -> httpx2.Response:
        """A trace file's bytes exactly as served: gzip-compressed."""
        return await self._send(self._station, "GET", f"/traces/{quote(name, safe='')}")

    async def phone_invite(self, body: PhoneInviteRequest) -> PhoneInvite:
        """An invite to stream a phone as camera `phone_<label>`."""
        response = await self._send(
            self._station, "POST", "/viewer/api/phone-invites", body
        )
        return TypeAdapter(PhoneInvite).validate_json(response.content)

    async def start_recording(self) -> str:
        """Start recording and return the recording's name."""
        response = await self._send(
            self._station, "POST", "/viewer/api/recording/start"
        )
        return TypeAdapter(str).validate_json(response.content)

    async def recording_status(self) -> RecordingStatus:
        """Whether the station is recording."""
        response = await self._send(
            self._station, "GET", "/viewer/api/recording/status"
        )
        return TypeAdapter(RecordingStatus).validate_json(response.content)

    async def stop_recording(self) -> None:
        """Stop recording."""
        await self._send(self._station, "POST", "/viewer/api/recording/stop")

    async def stop_recording_for_lease(self, body: LeaseToken) -> None:
        """Stop recording only while the token still holds the lease."""
        await self._send(
            self._station, "POST", "/viewer/api/recording/stop-for-lease", body
        )
